preConditionHook:
// THE MEASURED MOVE OFF A RANGE THAT IS STILL FORMING. While the pullback
// trading range builds, Brooks re-estimates the target every bar -- "keep
// adjusting the line" -- so the projection 2 * mid - legStart is recomputed
// from a ROLLING midpoint rather than frozen at the breakout. mid is the
// midpoint of the last rangeBars bars, current bar INCLUSIVE, and it moves
// with every new bar of the range.
//
// Same arithmetic as GapMidpointMeasuredMoveTarget, different behaviour: that
// rule freezes the whole level at entry, this one freezes only legStart and
// lets the midpoint walk, so the two fire on different bars. That is the only
// thing keeping them apart and it is the merge's stated reason.
//
// legLookback IS PROMOTED -- the merged parameters name no window for "the
// start of the pullback", and GapMidpointMeasuredMoveTarget's convention is a
// Lowest/Highest window, so legStart is the lowest low of legLookback bars for
// a long and the highest high for a short. It is captured ONCE, on the fill
// bar (ctx.BarsSinceEntry() == 0, VERIFIED 0 on the fill bar, 0 while flat,
// restarting through a reversal); a leg start recomputed every bar would slide
// with the market and take the target with it. Both windows are scanned
// UNCONDITIONALLY every bar -- only the freeze is conditional -- so Max Bars
// Back must cover them regardless, matching the twin's unconditional calls.
//
// THE GUARD: a leg start on the wrong side of the midpoint projects a target
// BEHIND the market, which a long would reach on its entry bar. haveUp /
// haveDn record, at the freeze, that legStart sat below (long) / above (short)
// the midpoint. At the defaults legLookback > rangeBars and the relation holds
// by construction, but the grid may invert them.
//
// Ticks division-first, ctx.MinMove() / ctx.PriceScale() computed once into
// tickSz: both are per-symbol constants (VERIFIED, exactly one change print
// per chart, at bar 1), so no history is needed.
//
// THE WINDOW SCANS mirror EasyLanguage's Extremes(), which Highest()/Lowest()
// call: seeded at bar 0, scanning bars 1..Length-1, and its comparison is an
// ordinary EL relational operator, so el_gt / el_lt rather than > and <.
//
// Not RangeMidpointTarget, which exits AT the midpoint of a window ending one
// bar ago; this projects THROUGH the midpoint to twice it less the leg start.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
tickSz = ctx.MinMove() / ctx.PriceScale();
rmHi = high[0];
rmLo = low[0];
for (int i = 1; i < (int)rangeBars; ++i) {
    if (el_gt(high[i], rmHi)) rmHi = high[i];
    if (el_lt(low[i], rmLo)) rmLo = low[i];
}
rmMid = (rmHi + rmLo) / 2;
legUp = low[0];
legDn = high[0];
for (int i = 1; i < (int)legLookback; ++i) {
    if (el_lt(low[i], legUp)) legUp = low[i];
    if (el_gt(high[i], legDn)) legDn = high[i];
}
if (ctx.BarsSinceEntry() == 0) {
    legStartUp = legUp;
    legStartDn = legDn;
    haveUp = el_lt(legUp, rmMid);
    haveDn = el_gt(legDn, rmMid);
}
tgtUp = 2 * rmMid - legStartUp;
tgtDn = 2 * rmMid - legStartDn;
